def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    groups = {}

    # Extract 4-connected objects by color.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            groups.setdefault(color, []).append(cells)

    # Put the color found farthest left in the left output group.
    colors = sorted(groups, key=lambda color: min(c for obj in groups[color] for r, c in obj))
    out = [[0] * w for _ in range(h)]

    widths = {}
    for color in colors:
        widths[color] = max(max(c for r, c in obj) - min(c for r, c in obj) + 1
                            for obj in groups[color])

    anchors = {}
    if colors:
        anchors[colors[0]] = 0
    if len(colors) > 1:
        anchors[colors[1]] = widths[colors[0]] + 1

    for color in colors:
        # Rightmost object goes in the upper slot; stack downwards with one
        # empty row between objects, ending at the bottom of the grid.
        objects = sorted(
            groups[color],
            key=lambda obj: sum(c for r, c in obj) / len(obj),
            reverse=True
        )
        heights = [max(r for r, c in obj) - min(r for r, c in obj) + 1
                   for obj in objects]
        total = sum(heights) + max(0, len(objects) - 1)
        top = h - total
        anchor = anchors.get(color, 0)

        for obj, height in zip(objects, heights):
            min_r = min(r for r, c in obj)
            min_c = min(c for r, c in obj)
            for r, c in obj:
                nr = top + r - min_r
                nc = anchor + c - min_c
                if 0 <= nr < h and 0 <= nc < w:
                    out[nr][nc] = color
            top += height + 1

    return out
